/* Papelera de reciclaje: restaurar o borrar lo eliminado en todas las unidades */
#include "z.h"
typedef struct { char dir[60], id[40], orig[300], when[40]; u64 size; int isdir; } it_t;
static zwin *W; static it_t *L; static int n, sel = -1, top; static char msg[120];
static void scan(void) { n = 0; zmount m[32]; int c = z_mounts(m, 32); for (int i = 0; i < c && n < 500; i++) { char d[60]; snprintf(d, 60, "/%s/.PAPELERA", m[i].name); zdirent e; for (int k = 0; n < 500 && !z_readdir(d, k, &e); k++) { if (!z_ends(e.name, ".info")) continue; it_t *t = &L[n]; strcpy(t->dir, d); strncpy0(t->id, e.name, 40); t->id[strlen(t->id) - 5] = 0; char p[120]; snprintf(p, 120, "%s/%s", d, e.name); char *s = z_readfile(p, 0); if (!s) continue; char *nl = strchr(s, '\n'); if (nl) *nl = 0; strncpy0(t->orig, s, 300); t->when[0] = 0; if (nl) { char *w = nl + 1, *x = strchr(w, '\n'); if (x) *x = 0; strncpy0(t->when, w, 40); } free(s); snprintf(p, 120, "%s/%s", d, t->id); zdirent st; if (z_stat(p, &st)) continue; t->size = st.size; t->isdir = st.is_dir; n++; } } if (sel >= n) sel = -1; }
static void rmt(const char *p) { zdirent d; if (z_stat(p, &d)) return; if (d.is_dir) { char *q = malloc(600); while (!z_readdir(p, 0, &d)) { snprintf(q, 600, "%s/%s", p, d.name); rmt(q); zdirent t; if (!z_stat(q, &t)) break; } free(q); } z_unlink(p); }
static void kill_(int i) { char p[120]; snprintf(p, 120, "%s/%s", L[i].dir, L[i].id); rmt(p); snprintf(p, 120, "%s/%s.info", L[i].dir, L[i].id); z_unlink(p); }
static void draw(void) { g_clear(W, UI_WHITE); g_rect(W, 0, 0, W->w, 40, UI_PANEL); ui_button(W, 8, 6, 110, 28, "Restaurar", sel >= 0 ? 2 : 0); ui_button(W, 124, 6, 150, 28, "Borrar del todo", 0); ui_button(W, 280, 6, 140, 28, "Vaciar papelera", 0); g_rect(W, 0, 40, W->w, 22, UI_BG); g_text(W, 12, 43, _("Nombre"), UI_MUTED); g_text(W, W->w / 2, 43, _("Ubicación original"), UI_MUTED); g_text(W, W->w - 150, 43, _("Borrado"), UI_MUTED); int vis = (W->h - 92) / 22; for (int i = top; i < n && i < top + vis; i++) { int y = 64 + (i - top) * 22; if (i == sel) g_rect(W, 0, y, W->w, 22, UI_ACC2); const char *b = strrchr(L[i].orig, '/'); g_rect(W, 10, y + 5, 12, 12, L[i].isdir ? 0xD97706 : 0x9CA3AF); zw_clip(W, 28, y, W->w / 2 - 34, 22); g_text(W, 30, y + 3, b ? b + 1 : L[i].orig, UI_TEXT); zw_clip(W, W->w / 2, y, W->w / 2 - 160, 22); g_text(W, W->w / 2, y + 3, L[i].orig, UI_MUTED); zw_noclip(W); g_text(W, W->w - 150, y + 3, L[i].when, UI_MUTED); } if (!n) g_text(W, 14, 70, _("La papelera está vacía."), UI_MUTED); g_rect(W, 0, W->h - 24, W->w, 24, UI_PANEL); char s[160]; snprintf(s, 160, "%d %s  %s", n, _("elementos"), msg); g_text(W, 8, W->h - 20, s, UI_TEXT); zw_present(W); }
static void restore(int i) { char src[120], dst[320]; snprintf(src, 120, "%s/%s", L[i].dir, L[i].id); strcpy(dst, L[i].orig); zdirent st; if (!z_stat(dst, &st)) { char *dot = strrchr(dst, '.'), *sl = strrchr(dst, '/'); char ext[40] = ""; if (dot && dot > sl) { strncpy0(ext, dot, 40); *dot = 0; } strcat(dst, _(" (restaurado)")); strcat(dst, ext); } char par[320]; strcpy(par, dst); *strrchr(par, '/') = 0; z_mkdir(par); int e = z_rename(src, dst); if (!e) { snprintf(src, 120, "%s/%s.info", L[i].dir, L[i].id); z_unlink(src); strcpy(msg, _("Restaurado")); z_log("[prueba] papelera restauro"); } else snprintf(msg, 120, "%s", z_errstr(e)); }
int main(const char *a) { L = malloc(500 * sizeof *L); W = zw_new("Papelera", -1, 0, 720, 420, WF_DECOR | WF_RESIZE); scan(); draw(); zevent e; for (;;) { if (!z_event(&e, 3000)) { scan(); draw(); continue; } if (e.type == EV_REDRAW) { draw(); continue; } if (e.win != (u32)W->id) continue; if (e.type == EV_CLOSE) return 0; if (e.type == EV_RESIZE) zw_resized(W, e.x, e.y); else if (e.type == EV_WHEEL) top = MAX(0, MIN(top - (int)e.key * 3, n - 1)); else if (e.type == EV_DOWN) { msg[0] = 0; if (e.y < 40) { if (e.x < 118 && sel >= 0) restore(sel); else if (e.x >= 124 && e.x < 274 && sel >= 0) { if (ui_confirm("Borrar del todo", "Se borrará para siempre. ¿Seguir?")) { kill_(sel); z_sync(); } } else if (e.x >= 280 && e.x < 420 && n) { if (ui_confirm("Vaciar papelera", "Se borrará todo para siempre. ¿Seguir?")) { for (int i = 0; i < n; i++) kill_(i); z_sync(); z_log("[prueba] papelera vaciada"); } } scan(); } else if (e.y >= 64) { int i = top + (e.y - 64) / 22; sel = i < n ? i : -1; if (sel >= 0 && (e.btn & 2)) { static const char *it[] = {"Restaurar", "Borrar del todo"}; int sx, sy; zw_screen(W, e.x, e.y, &sx, &sy); int r = ui_menu(sx, sy, it, 2); if (r == 0) restore(sel); else if (r == 1 && ui_confirm("Borrar del todo", "Se borrará para siempre. ¿Seguir?")) kill_(sel); scan(); } } } else if (e.type == EV_KEY && e.key == 0x4C && sel >= 0) { if (ui_confirm("Borrar del todo", "Se borrará para siempre. ¿Seguir?")) { kill_(sel); scan(); } } else continue; draw(); } }
